{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.saadaa_returns_consolidated as select s.order_name as reference_code ,s.Line_Item_ID as saleorderitemcode ,s.order_id ,s.order_status ,cast(DATETIME(TIMESTAMP(order_timestamp)) as date) AS Order_Date ,UPPER(s.marketplace) as marketplace ,UPPER(coalesce(GA4.CHANNEL,s.FINAL_UTM_CHANNEL)) as marketing_channel ,UPPER(coalesce(GA4.final_source,s.FINAL_UTM_SOURCE)) as source ,UPPER(s.product_name) as product_name ,coalesce(r.returned_sku,s.sku) as sku ,upper(s.category) as product_category ,upper(s.PRODUCT_SUB_CATEGORY) as product_sub_category ,s.quantity as order_quantity ,s.city ,s.state ,s.pincode ,s.courier as shipping_courier ,s.awb ,s.name as customer_name ,s.email as customer_email ,cast(datetime(timestamp(r.created_at)) as datetime) as return_requested_date ,r.return_approval_status ,r.return_request_type ,(case when r.return_flag is not null then r.return_flag else 0 end) as return_flag ,r.return_date ,r.returned_quantity as TOTAL_RETURNED_QUANTITY ,r.return_reason ,s.payment_mode ,s.total_sales ,r.returned_product_name ,r.returned_product_variant ,r.returned_sku ,cast(r.returned_product_price as float64) as returned_product_price ,(case when return_flag = 1 then s.tax else 0 end) as TOTAL_RETURN_TAX ,(cast(r.returned_product_price as float64) - (case when return_flag = 1 then s.tax else 0 end)) as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.return_line_item_id as returned_item_saleorderitemcode ,r.exchange_product_name ,r.exchange_product_variant ,r.exchange_sku ,r.exchange_product_total_price ,r.exchange_status ,r.refunded_at ,c.order_status as oms_order_status from saadaa-wh.maplemonk.saadaa_shopify_fact_items s left join saadaa-wh.maplemonk.saadaa_returnsprime_consolidated r on s.order_name = r.order_name and s.line_item_id = r.order_item_id left join (select transactionid, final_source, channel from maplemonk.SAADAA_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) =1 ) GA4 on replace(s.order_name,\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from maplemonk.SAADAA_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(s.order_name,\'#\',\'\') = replace(c.reference_code,\'#\',\'\') and replace(s.LINE_ITEM_ID,\'`\',\'\')=replace(c.Marketplace_LineItem_ID,\'`\',\'\') UNION ALL select e.reference_code ,e.Marketplace_LineItem_ID AS SALEORDERITEMCODE ,e.ORDER_ID ,Upper(e.order_status) as order_status ,cast(e.ORDER_DATE as datetime) AS Order_Date ,UPPER(e.marketplace) AS marketplace ,UPPER(e.marketplace) AS MARKETING_CHANNEL ,UPPER(e.marketplace) AS SOURCE ,UPPER(e.PRODUCTNAME) AS PRODUCT_NAME ,e.SKU ,UPPER(e.mapped_category) AS product_category ,UPPER(e.mapped_sub_category) AS product_sub_category ,e.suborder_quantity as order_quantity ,UPPER(e.CITY) AS City ,UPPER(e.STATE) AS State ,e.pincode ,UPPER(e.COURIER) AS Shipping_Courier ,e.awb ,e.customer_name AS NAME ,e.email AS EMAIL ,cast(null as datetime) as return_requested_date ,\'Aprroved\' as return_approval_status ,null as return_request_type ,e.is_refund as return_flag ,cast(r.return_date as date) as return_date ,r.RETURNED_QUANTITY as TOTAL_RETURNED_QUANTITY ,e.Payment_mode ,r.return_reason ,e.selling_price ,r.PRODUCTNAME as returned_product_name ,r.RETURNED_PRODUCT_SIZE as returned_product_variant ,r.SKU as returned_sku ,r.TOTAL_RETURN_AMOUNT ,case when e.is_refund = 1 then e.tax else 0 end as TOTAL_RETURN_TAX ,r.RETURN_AMOUNT_WITHOUT_TAX as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.suborder_num as returned_item_saleorderitemcode ,cast(null as string) as exchange_product_name ,cast(null as string) as exchange_product_variant ,cast(null as string) as exchange_sku ,null as exchange_product_total_price ,cast(null as string) as exchange_status ,r.return_date as refunded_at ,e.order_status as oms_order_status from maplemonk.saadaa_easyecom_fact_items e left join maplemonk.SAADAA_easyecom_returns_intermediate r on e.reference_code = r.reference_code and e.marketplace_lineitem_id = r.suborder_num where not(lower(e.marketplace) like \'%shopify%\' or lower(e.marketplace) like \'%amazon%\') UNION ALL select a.order_id as reference_code ,concat(a.order_id,\'-\',a.product_id) as saleorderitemcode ,a.order_id ,upper(a.order_status) as order_status ,cast(a.order_timestamp as date) as order_date ,\'AMAZON\' AS marketplace ,\'AMAZON\' AS marketing_CHANNEL ,\'AMAZON\' AS SOURCE ,a.product_name ,a.sku ,a.product_category ,a.product_sub_category ,a.quantity as order_quantity ,a.city ,a.state ,e.pincode ,e.courier as shipping_courier ,e.awb ,a.name as customer_name ,coalesce(e.email,a.email) as customer_email ,cast(null as date) as return_date ,\'Approved\' as return_approval_status ,\'return\' as return_request_type ,a.is_refund as return_flag ,cast(r.return_date as date) as return_date ,r.RETURNED_QUANTITY as TOTAL_RETURNED_QUANTITY ,e.Payment_mode ,r.return_reason ,e.selling_price ,r.PRODUCTNAME as returned_product_name ,r.RETURNED_PRODUCT_SIZE as returned_product_variant ,r.SKU as returned_sku ,r.TOTAL_RETURN_AMOUNT as returned_product_price ,case when a.is_refund = 1 then a.tax else 0 end as TOTAL_RETURN_TAX ,r.RETURN_AMOUNT_WITHOUT_TAX as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.suborder_num as returned_item_saleorderitemcode ,cast(null as string) as exchange_product_name ,cast(null as string) as exchange_product_variant ,cast(null as string) as exchange_sku ,null as exchange_product_total_price ,cast(null as string) as exchange_status ,r.return_date as refunded_at ,e.order_status as oms_order_status from maplemonk.saadaa_amazon_fact_items a left join ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw FROM maplemonk.SAADAA_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%amazon%\' )e on a.ordeR_id = e.reference_code and a.sku = e.sku full outer join ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw1 FROM maplemonk.SAADAA_easyecom_returns_intermediate ) z1 WHERE z1.rw1 = 1 AND LOWER(marketplace) LIKE \'%amazon%\' ) r on a.order_id = r.reference_code and a.sku= r.SKU ; create or replace table saadaa-wh.maplemonk.saadaa_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, DATE_TRUNC(order_Date, MONTH) as month_first_date, count(distinct reference_code) as orders_for_the_month, COUNT(DISTINCT CASE WHEN return_flag = 1 THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(return_flag) as total_returned_items_for_orders_of_month, count(*) as total_order_items_for_the_month FROM saadaa-wh.maplemonk.saadaa_returns_consolidated GROUP BY order_month,month_first_date ), returns as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, COUNT(*) as total_returned_items_received_in_month, count(distinct reference_code) as returned_orders_received_in_month, FROM saadaa-wh.maplemonk.saadaa_returns_consolidated WHERE return_flag = 1 GROUP BY return_month ) SELECT o.month_first_date, o.order_month, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, r.total_returned_items_received_in_month, r.returned_orders_received_in_month from orders o LEFT JOIN returns r ON r.return_month = o.order_month order by order_month desc;",
                    "transaction": true
                }
            ) }}
